\set ON_ERROR_STOP on
begin;
insert into auth.users values('00000000-0000-4000-8000-000000000001'),('00000000-0000-4000-8000-000000000002'),('00000000-0000-4000-8000-000000000003');
insert into public.liqa_staff values('00000000-0000-4000-8000-000000000001','Marketer A','marketer',true),('00000000-0000-4000-8000-000000000002','Marketer B','marketer',true),('00000000-0000-4000-8000-000000000003','Admin','admin',true);
create function pg_temp.assert_true(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAILED: %',label; end if;raise notice 'PASS: %',label;end$$;
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
insert into public.liqa_offices(id,name,city,contact,assigned_to,created_by) values('00000000-0000-4000-8000-000000000011','Office A','Riyadh','Test A',auth.uid(),auth.uid());
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000002',true);
insert into public.liqa_offices(id,name,city,contact,assigned_to,created_by) values('00000000-0000-4000-8000-000000000012','Office B','Riyadh','Test B',auth.uid(),auth.uid());
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
select pg_temp.assert_true((select count(*)=1 from public.liqa_offices),'marketer sees only assigned office');
select pg_temp.assert_true((select count(*)=1 from public.liqa_staff),'marketer sees only own staff row');
select pg_temp.assert_true((select count(*)=1 from public.liqa_audit),'audit scoped by office');
do $$begin begin update public.liqa_staff set role='admin' where user_id=auth.uid();raise division_by_zero;exception when insufficient_privilege then null;end;end$$;
select pg_temp.assert_true(liqa_private.staff_role()='marketer','self-escalation denied');
do $$begin begin update public.liqa_offices set assigned_to='00000000-0000-4000-8000-000000000002';raise division_by_zero;exception when insufficient_privilege or raise_exception then null;end;end$$;
select pg_temp.assert_true((select assigned_to=auth.uid() from public.liqa_offices),'reassignment denied');
do $$declare n integer;begin update public.liqa_offices set name='Forbidden' where id='00000000-0000-4000-8000-000000000012';get diagnostics n=row_count;perform pg_temp.assert_true(n=0,'cross-office update affects no rows');end$$;
do $$begin begin perform public.liqa_command('note','00000000-0000-4000-8000-000000000012','{"text":"forbidden"}');raise division_by_zero;exception when raise_exception then null;end;end$$;
do $$begin begin perform public.liqa_command('interest','00000000-0000-4000-8000-000000000011');raise division_by_zero;exception when raise_exception then null;end;end$$;
select pg_temp.assert_true((select interested_at is null from public.liqa_offices),'interest requires consent');
do $$begin begin perform public.liqa_command('interview','00000000-0000-4000-8000-000000000011','{"workflow":"WhatsApp","researchConsent":false}');raise division_by_zero;exception when raise_exception then null;end;end$$;
select pg_temp.assert_true((select count(*)=0 from public.liqa_interviews),'interview requires distinct research consent');
do $$begin begin insert into public.liqa_interviews(office_id,workflow,research_consent,prices) values('00000000-0000-4000-8000-000000000011','WhatsApp',true,'[200,100,300,400]');raise division_by_zero;exception when check_violation then null;end;end$$;
select pg_temp.assert_true((select count(*)=0 from public.liqa_interviews),'invalid price order denied at database layer');
select public.liqa_command('note','00000000-0000-4000-8000-000000000011','{"text":"A note"}');
select pg_temp.assert_true((select count(*)=1 from public.liqa_notes),'authorized note persists');
select pg_temp.assert_true((select count(*)=2 from public.liqa_audit),'note creates server audit entry');
do $$begin begin insert into public.liqa_audit(office_id,actor,action) values('00000000-0000-4000-8000-000000000011',auth.uid(),'forged');raise division_by_zero;exception when insufficient_privilege then null;end;end$$;
do $$begin begin insert into public.liqa_subscriptions(office_id,status,paid_at,provider_reference) values('00000000-0000-4000-8000-000000000011','active',now(),'fake-payment');raise division_by_zero;exception when insufficient_privilege then null;end;end$$;
select pg_temp.assert_true((select count(*)=0 from public.liqa_subscriptions),'marketer cannot forge payment');
do $$begin begin perform public.liqa_command('trial','00000000-0000-4000-8000-000000000011');raise division_by_zero;exception when insufficient_privilege then null;end;end$$;
do $$begin begin perform public.liqa_command('edit','00000000-0000-4000-8000-000000000011','{"version":999}');raise division_by_zero;exception when raise_exception then null;end;end$$;
select pg_temp.assert_true((select version=1 from public.liqa_offices),'stale version rejected without mutation');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000003',true);
select pg_temp.assert_true((select count(*)=2 from public.liqa_offices),'admin sees both offices');
select pg_temp.assert_true((select count(*)=3 from public.liqa_staff),'admin sees staff assignments');
update public.liqa_offices set consent_at=now(),interested_at=now() where id='00000000-0000-4000-8000-000000000011';
select public.liqa_command('trial','00000000-0000-4000-8000-000000000011');
select pg_temp.assert_true((select trial_at is not null from public.liqa_offices where id='00000000-0000-4000-8000-000000000011'),'admin records agreed trial');
reset role;
update public.liqa_staff set active=false where user_id='00000000-0000-4000-8000-000000000001';
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
select pg_temp.assert_true((select count(*)=0 from public.liqa_offices),'disabled staff sees no offices');
set local role anon;
do $$begin begin perform * from public.liqa_offices;raise division_by_zero;exception when insufficient_privilege then null;end;end$$;
reset role;
rollback;
\echo 'All database authorization and lifecycle assertions passed (disposable PostgreSQL with auth.uid stand-in).'
